func TestCredentialTable_NoDuplicateIDs(t *testing.T) {
	seen := make(map[string]bool)
	for _, e := range credentialPaths {
		if seen[e.ID] {
			t.Errorf("duplicate credential entry ID: %s", e.ID)
		}
		seen[e.ID] = true
