}

func TestCredentialTable_ValidSeverities(t *testing.T) {
	for _, e := range credentialPaths {
		if !validSeverities[e.Severity] {
			t.Errorf("entry %s has invalid severity %q", e.ID, e.Severity)
		}
	}
