	initGitRepo(t, gitRepoPath)

	// Set token env vars — these should not affect file:// clones
	t.Setenv("GITHUB_TOKEN", "ghp_fake_token_12345")
	t.Setenv("GITLAB_TOKEN", "glpat-fake-token")

