	t.Setenv("GITHUB_TOKEN", "ghp_should_not_break_file_pull")

	// Update via CLI — exercises getRemoteURL + authEnv + gitPull
	updateResult := sb.RunCLI("install", "tracked-auth-skill", "--update")
